for cell in &cells {
        cell.validazione_protetta().map_err(classifica_cella)?;
    }

for faccia in triangolazione.inner_faces() {
        let [a, b, c] = faccia.vertices().map(|vertice| *vertice.data());
        let (centro, errore) = circocentro_maggiorato(a, b, c);
        // `errore` puo' essere NaN o infinito: si rifiuta anche allora.
        if !matches!(
            errore.partial_cmp(&(p / 4.0)),
            Some(std::cmp::Ordering::Less | std::cmp::Ordering::Equal)
        ) {
            return Err(AdvancedError::VerticeMalCondizionato);
        }
        if let Some(posto) = circocentri.get_mut(faccia.fix().index()) {
            *posto = centro;
        }
    }

for face in triangolazione.voronoi_faces() {
        let edges: Vec<_> = face.adjacent_edges().collect();
        if edges.is_empty() {
            continue;
        }

        let sito = *face.as_delaunay_vertex().data();
        let site_coord = sito.coordinata;

        // Circocentri e raggi della cella.
        let mut circumcenters: Vec<Coord<f64>> = Vec::new();
        let mut rays: Vec<(Coord<f64>, Coord<f64>)> = Vec::new(); // (origine, direzione)

        for edge in &edges {
            let from_vertex = edge.from();
            let to_vertex = edge.to();

            if let Inner(inner_face) = &from_vertex {
                let coord = centro_della_faccia(inner_face.fix().index());
                if !circumcenters.contains(&coord) {
                    circumcenters.push(coord);
                }
            }
            if let Inner(inner_face) = &to_vertex {
                let coord = centro_della_faccia(inner_face.fix().index());
                if !circumcenters.contains(&coord) {
                    circumcenters.push(coord);
                }
            }

            // Un lato verso l'esterno e' un raggio dal circocentro.
            if let (Inner(inner_face), Outer(outer_edge)) = (&from_vertex, &to_vertex) {
                let ref_pt = centro_della_faccia(inner_face.fix().index());
                let dir = outer_edge.direction_vector();
                rays.push((ref_pt, Coord { x: dir.x, y: dir.y }));
            }

            if let (Outer(outer_edge), Inner(inner_face)) = (&from_vertex, &to_vertex) {
                let ref_pt = centro_della_faccia(inner_face.fix().index());
                let dir = outer_edge.direction_vector();
                rays.push((ref_pt, Coord { x: dir.x, y: dir.y }));
            }
        }

        // I vertici della cella.
        let mut vertices: Vec<Coord<f64>> = circumcenters.clone();

        if rays.is_empty() {
            // Cella interna: solo circocentri.
            if vertices.len() < 3 {
                continue;
            }
        } else {
            // Cella di bordo: i raggi si prolungano ben oltre il rettangolo.
            for (origin, direction) in &rays {
                // Direzione unitaria, cosi' ogni raggio si prolunga della
                // stessa distanza; si saltano le direzioni nulle o non
                // finite.
                let Some(unit_dir) = direction.try_normalize() else {
                    continue;
                };

                // Un punto lontano oltre il rettangolo, lungo il raggio.
                let extended = *origin + unit_dir * extension;
                vertices.push(extended);
            }
        }

        if vertices.len() < 3 {
            continue;
        }

        // Vertici in ordine d'angolo attorno al sito.
        vertices.sort_by(|a, b| {
            let angle_a = f64::atan2(a.y - site_coord.y, a.x - site_coord.x);
            let angle_b = f64::atan2(b.y - site_coord.y, b.x - site_coord.x);
            angle_a.total_cmp(&angle_b)
        });

        let Some(&primo) = vertices.first() else {
            continue;
        };
        vertices.push(primo);
        let poly = Polygon::new(LineString::new(vertices), vec![]);

        if let Some(posto) = per_rango.get_mut(sito.rango) {
            *posto = Some(poly);
        }
    }

for edge in &edges {
            let from_vertex = edge.from();
            let to_vertex = edge.to();

            if let Inner(inner_face) = &from_vertex {
                let coord = centro_della_faccia(inner_face.fix().index());
                if !circumcenters.contains(&coord) {
                    circumcenters.push(coord);
                }
            }
            if let Inner(inner_face) = &to_vertex {
                let coord = centro_della_faccia(inner_face.fix().index());
                if !circumcenters.contains(&coord) {
                    circumcenters.push(coord);
                }
            }

            // Un lato verso l'esterno e' un raggio dal circocentro.
            if let (Inner(inner_face), Outer(outer_edge)) = (&from_vertex, &to_vertex) {
                let ref_pt = centro_della_faccia(inner_face.fix().index());
                let dir = outer_edge.direction_vector();
                rays.push((ref_pt, Coord { x: dir.x, y: dir.y }));
            }

            if let (Outer(outer_edge), Inner(inner_face)) = (&from_vertex, &to_vertex) {
                let ref_pt = centro_della_faccia(inner_face.fix().index());
                let dir = outer_edge.direction_vector();
                rays.push((ref_pt, Coord { x: dir.x, y: dir.y }));
            }
        }

for (origin, direction) in &rays {
                // Direzione unitaria, cosi' ogni raggio si prolunga della
                // stessa distanza; si saltano le direzioni nulle o non
                // finite.
                let Some(unit_dir) = direction.try_normalize() else {
                    continue;
                };

                // Un punto lontano oltre il rettangolo, lungo il raggio.
                let extended = *origin + unit_dir * extension;
                vertices.push(extended);
            }

for cell in raw_cells {
        // Una cella tutta dentro il rettangolo di ritaglio non si interseca.
        let cell_rect = cell.bounding_rect();
        let contained_by_clip = clip_rect
            .as_ref()
            .zip(cell_rect)
            .is_some_and(|(cr, cell_rect)| cr.contains(&cell_rect));

        if contained_by_clip {
            celle.push(cell);
        } else {
            // Il ritaglio passa dalla griglia di `i_overlay`: lo stesso
            // controllo a priori delle booleane (`p / 2`, che con i vertici
            // entro `p / 4` resta nella precisione).
            griglia::controlla_overlay(griglia::unisci(clip_rect, cell_rect), precision)
                .map_err(|_| AdvancedError::PrecisionInsufficient)?;
            celle.extend(cell.intersection(&clip_poly).0);
        }
    }

for &candidato in &candidati {
                let Some((cell, bounds)) = cells.get(candidato).zip(cell_bounds.get(candidato))
                else {
                    continue;
                };
                if protetto(|| cella_accetta(cell, bounds.as_ref(), point))? {
                    return Ok(Geometry::Polygon(cell.clone()));
                }
            }

for (index, geometry) in geometries.iter().enumerate() {
        let Some(geometry) = geometry else {
            continue;
        };
        if geometry
            .coords_iter()
            .any(|coordinate| !coordinate.x.is_finite() || !coordinate.y.is_finite())
        {
            return Err(AnalysisError::InvalidGeometry {
                side,
                index,
                reason: "coordinate NaN o infinite".to_owned(),
            });
        }
        geometry.validazione_protetta().map_err(|esito| {
            esito.separa(
                |ragione| AnalysisError::InvalidGeometry {
                    side,
                    index,
                    reason: ragione.to_string(),
                },
                AnalysisError::ValidazioneNonConclusa,
            )
        })?;
    }

for right in &usable_right {
                let distanza = distanza_protetta(geometry, right)?;
                minimo = Some(minimo.map_or(distanza, |attuale| attuale.min(distanza)));
            }

for group in groups {
        match group {
            Ok(group) => matches.extend(group),
            Err(
                error @ (AnalysisError::ResultLimitExceeded { .. }
                | AnalysisError::MargineMemoria(_)),
            ) => {
                limite_superato.get_or_insert(error);
            }
            Err(error) => return Err(error),
        }
    }

for (posizione, (_, geometria)) in usable_right.iter().enumerate() {
            match involucro_regolare(geometria) {
                Some((envelope, modulo)) => {
                    modulo_right = modulo_right.max(modulo);
                    involucri.push(InvolucroRight {
                        envelope,
                        posizione,
                    });
                }
                None => sempre.push(posizione),
            }
        }

for candidato in self.albero.locate_in_envelope_intersecting(&finestra) {
            primo_visto |= candidato.posizione == primo.posizione;
            visita(candidato.posizione)?;
        }

for posizione in &self.sempre {
            visita(*posizione)?;
        }

for coordinata in geometria.coords_iter() {
        for valore in [coordinata.x, coordinata.y] {
            let assoluto = valore.abs();
            // NaN non passa: nessuno dei due confronti e' vero.
            let nel_dominio = valore == 0.0 || (MODULO_MINIMO..=MODULO_MASSIMO).contains(&assoluto);
            if !nel_dominio {
                return None;
            }
            modulo = modulo.max(assoluto);
        }
    }

for pair in pairs {
        let index = usize::try_from(pair.right).map_err(|_| AnalysisError::IndexOverflow)?;
        counts[index] = counts[index]
            .checked_add(1)
            .ok_or(AnalysisError::IndexOverflow)?;
    }

for pair in pairs {
        let index = usize::try_from(pair.right).map_err(|_| AnalysisError::IndexOverflow)?;
        counts[index] = counts[index]
            .checked_add(1)
            .ok_or(AnalysisError::IndexOverflow)?;
    }

for candidate in &mut geometries {
        if candidate.field_id == geometry.field_id {
            candidate.nullable = true;
        }
    }

for campo in &mut fields {
        if campo.name() == &geometry.name {
            *campo = crate::riproiezione::campo_riproiettato(
                campo,
                &target,
                geometry.dimensions,
                geometry.encoding,
            )?;
        }
    }

for candidate in &mut geometries {
        if candidate.field_id == field_id {
            candidate.nullable = nullable;
        }
    }

for name in &parsed.group_by {
        if !ensure_name(name) {
            return Err(invalid_param(op, "group_by", "nomi colonna non vuoti"));
        }
        if input.geometries.iter().any(|g| &g.name == name) {
            return Err(invalid_param(
                op,
                "group_by",
                "la colonna geometria non puo' essere chiave di gruppo",
            ));
        }
        let field = input.schema.field_with_name(name).map_err(|_| {
            PlenoraError::Schema(format!("{op}: colonna `{name}` assente dallo schema"))
        })?;
        if extra.iter().any(|(seen, _)| seen.name() == name) {
            return Err(invalid_param(op, "group_by", "colonne duplicate"));
        }
        // I gruppi escono nell'ordine naturale dei valori, con il
        // comparatore di `table.sort` (`compare_cells_typed`): un tipo che
        // non ha un confronto nativo si rifiuta qui, non in esecuzione.
        if !plenora_kernels_table::aggregation::is_sortable(field.data_type()) {
            return Err(PlenoraError::InvalidPlan(format!(
                "{op}: parametro `group_by` non valido: colonna `{name}` di tipo {} senza \
                 un ordine naturale",
                plenora_core::tipo_arrow::descrivi_tipo(field.data_type())
            )));
        }
        // La colonna chiave sopravvive invariata: si clona il `Field`
        // intero, metadati compresi.
        let index = input.schema.index_of(name)?;
        extra.push((field.clone(), input.field_origins()[index]));
    }

for (index, input) in inputs.iter().enumerate() {
        input.validate()?;
        if producer {
            operands.push(None);
            continue;
        }
        let key = keys
            .get(index)
            .ok_or_else(|| PlenoraError::InvalidPlan("arieta' geo non valida".into()))?;
        let value = object.remove(*key);
        let name = value
            .as_ref()
            .map(|value| {
                value
                    .as_str()
                    .filter(|name| !name.trim().is_empty())
                    .ok_or_else(|| {
                        PlenoraError::InvalidPlan(
                            "selettore geometrico non valido: atteso nome non vuoto".into(),
                        )
                    })
            })
            .transpose()?;
        let geometry = if let Some(name) = name {
            input
                .geometries
                .iter()
                .find(|geometry| geometry.name == name)
                .ok_or_else(|| {
                    PlenoraError::Schema(
                        "selettore riferito a una colonna assente o non geometrica".into(),
                    )
                })?
        } else {
            input.select_geometry(None)?
        };
        operands.push(Some(geometry));
    }

for input in &mut owned_inputs {
        input.validate()?;
        for id in input.field_ids.values() {
            fields.observe(*id);
        }
    }

for id in input.field_ids.values() {
            fields.observe(*id);
        }

for input in &mut owned_inputs {
        fields.bind_contract(input);
        for field in input.schema.fields() {
            let id = fields.intern(field.name())?;
            input.field_ids.insert(field.name().clone(), id);
        }
    }

for field in input.schema.fields() {
            let id = fields.intern(field.name())?;
            input.field_ids.insert(field.name().clone(), id);
        }

for (input, selected) in owned_inputs.iter_mut().zip(selected_ids) {
        // Solo l'operando puo' essere riscritto; le secondarie passano invariate.
        if selected.is_some_and(|id| {
            input
                .properties
                .sorted_by
                .as_ref()
                .and_then(|property| property.value())
                .is_some_and(|order| order.keys.contains(&id))
        }) {
            input.properties.sorted_by = None;
        }
    }

for (input, geometry) in inputs.iter().zip(&operands) {
        if let Some(geometry) = geometry {
            richiedi_assi_operando(descriptor.id, input, geometry)?;
        }
    }

for (index, &coords) in points.iter().enumerate() {
        let key = coordinate_key(coords);
        let group = if let Some(&group) = group_by_coordinate.get(&key) {
            group
        } else {
            let group = representatives.len();
            group_by_coordinate.insert(key, group);
            representatives.push(index);
            group
        };
        group_of_point.push(group);
    }

for index in 0..points.len() {
        if visited[index] {
            continue;
        }
        visited[index] = true;
        let group = group_of_point[index];
        let Some(seed) = load_core_neighbors(
            &tree,
            points,
            neighborhood_parameters,
            &representatives,
            group,
            &mut neighborhood_class,
            &mut range_queries,
        )?
        else {
            continue; // noise provvisorio: puo' diventare border
        };
        peak_retained_neighbor_indices = peak_retained_neighbor_indices.max(seed.len());
        let cluster = next_cluster;
        next_cluster = next_cluster
            .checked_add(1)
            .ok_or(ClusterError::IndexOverflow)?;
        labels[index] = Some(cluster);
        queued[index] = true;
        expanded_group[group] = true;
        let mut queue: VecDeque<usize> = VecDeque::new();
        for &member in &seed {
            if member != index {
                queued[member] = true;
                queue.push_back(member);
            }
        }
        while let Some(member) = queue.pop_front() {
            if !visited[member] {
                visited[member] = true;
                let member_group = group_of_point[member];
                if !expanded_group[member_group] {
                    let expanded = load_core_neighbors(
                        &tree,
                        points,
                        neighborhood_parameters,
                        &representatives,
                        member_group,
                        &mut neighborhood_class,
                        &mut range_queries,
                    )?;
                    if let Some(expanded) = expanded {
                        peak_retained_neighbor_indices =
                            peak_retained_neighbor_indices.max(expanded.len());
                        for &reach in &expanded {
                            if !queued[reach] {
                                queued[reach] = true;
                                queue.push_back(reach);
                            }
                        }
                    }
                    expanded_group[member_group] = true;
                }
            }
            if labels[member].is_none() {
                labels[member] = Some(cluster);
            }
        }
    }

for &member in &seed {
            if member != index {
                queued[member] = true;
                queue.push_back(member);
            }
        }

while let Some(member) = queue.pop_front() {
            if !visited[member] {
                visited[member] = true;
                let member_group = group_of_point[member];
                if !expanded_group[member_group] {
                    let expanded = load_core_neighbors(
                        &tree,
                        points,
                        neighborhood_parameters,
                        &representatives,
                        member_group,
                        &mut neighborhood_class,
                        &mut range_queries,
                    )?;
                    if let Some(expanded) = expanded {
                        peak_retained_neighbor_indices =
                            peak_retained_neighbor_indices.max(expanded.len());
                        for &reach in &expanded {
                            if !queued[reach] {
                                queued[reach] = true;
                                queue.push_back(reach);
                            }
                        }
                    }
                    expanded_group[member_group] = true;
                }
            }
            if labels[member].is_none() {
                labels[member] = Some(cluster);
            }
        }

for &reach in &expanded {
                            if !queued[reach] {
                                queued[reach] = true;
                                queue.push_back(reach);
                            }
                        }

for (index, geometry) in geometries.iter().enumerate() {
        let Some(geometry) = geometry else {
            row_of_point.push(None);
            continue;
        };
        if geometry
            .coords_iter()
            .any(|coordinate| !coordinate.x.is_finite() || !coordinate.y.is_finite())
        {
            return Err(ClusterError::NonFiniteCoordinate { index });
        }
        geometry.validazione_protetta().map_err(|esito| {
            esito.separa(
                |ragione| ClusterError::InvalidGeometry {
                    index,
                    reason: ragione.to_string(),
                },
                ClusterError::ValidazioneNonConclusa,
            )
        })?;
        let Geometry::Point(point) = geometry else {
            return Err(ClusterError::UnsupportedGeometry {
                index,
                found: geometry_name(geometry),
            });
        };
        row_of_point.push(Some(points.len()));
        points.push([point.x(), point.y()]);
    }

for (posizione, carattere) in testo[apertura..].char_indices() {
        match carattere {
            '(' => profondita += 1,
            ')' => {
                profondita = profondita.saturating_sub(1);
                if profondita == 0 {
                    let resto = &testo[apertura + posizione + 1..];
                    return !resto.chars().all(spazio_wkt);
                }
            }
            _ => {}
        }
    }

for ring_index in 0..rings {
                let count = cursor.read_u32(little_endian)?;
                let count = checked_count(count, cursor.remaining(), stride)?;
                cursor.skip(count * stride)?;
                *total = total.saturating_add(COORD_BYTES.saturating_mul(count as u64));
                // Anelli interni: header `LineString` nel buffer degli
                // interni (l'esterno e' inline nel `Polygon`).
                if ring_index > 0 {
                    *total = total.saturating_add(LINESTRING_BYTES);
                }
            }

for _ in 0..children {
                let child_type =
                    decoded_size_geometry(cursor, depth + 1, max_depth, components, total)?;
                // Controllo per figlio, immediatamente dopo la sua
                // camminata: stesso ordine del decoder.
                let compatible = match geometry_type {
                    4 => child_type == 1,
                    5 => child_type == 2,
                    6 => child_type == 3,
                    _ => true,
                };
                if !compatible {
                    return Err(invalid_wkb_structure(
                        "tipo figlio incompatibile con multi-geometria",
                    ));
                }
                // Slot del figlio nel buffer del contenitore (inline).
                let slot = match geometry_type {
                    4 => POINT_BYTES,
                    5 => LINESTRING_BYTES,
                    6 => POLYGON_BYTES,
                    _ => GEOMETRY_BYTES,
                };
                *total = total.saturating_add(slot);
            }

for (a, b) in left.iter().zip(right.iter()) {
        let ordering = cmp_coord(a, b);
        if ordering != Ordering::Equal {
            return ordering;
        }
    }

for (a, b) in left.interiors().iter().zip(right.interiors().iter()) {
            let ordering = cmp_line_string(a, b);
            if ordering != Ordering::Equal {
                return ordering;
            }
        }

for start in 1..open.len() {
        let candidate: Vec<Coord<f64>> = open[start..]
            .iter()
            .chain(open[..start].iter())
            .copied()
            .collect();
        if cmp_coords(&candidate, &best) == Ordering::Less {
            best = candidate;
        }
    }

for coordinate in line.coords() {
        validate_geographic_point(Point::from(*coordinate))?;
    }

for segment in line.lines() {
        let dx = segment.end.x - segment.start.x;
        let dy = segment.end.y - segment.start.y;
        let length = dx.hypot(dy);
        let pieces = (length / max_segment_length).ceil();
        // Soglia 2^64, esatta in f64: `u64::MAX as f64` arrotonda per
        // eccesso proprio a 2^64, che non e' un `u64`. Si rifiuta anche
        // l'uguaglianza: con `>` il valore 2^64 passerebbe e il cast
        // saturante lo renderebbe `u64::MAX`, un conteggio sbagliato.
        if !pieces.is_finite() || pieces >= 18_446_744_073_709_551_616.0 {
            return Err(ExtendedAlgorithmError::IndexOverflow);
        }
        // Guardia sopra: pieces finito, in [0, 2^64) e a valore intero
        // (ceil di un rapporto non negativo, max_segment_length > 0); il
        // cast non puo' perdere segno, troncare ne' saturare.
        #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
        let pieces_u64 = (pieces as u64).max(1);
        total = total
            .checked_add(pieces_u64)
            .ok_or(ExtendedAlgorithmError::IndexOverflow)?;
    }

for ring in polygon.interiors() {
                total = total
                    .checked_add(checked_densified_line_count(ring, max_segment_length)?)
                    .ok_or(ExtendedAlgorithmError::IndexOverflow)?;
            }

for faccia in &mut facce {
        let [a, b, c] = *faccia;
        *faccia = if b.rango < a.rango && b.rango < c.rango {
            [b, c, a]
        } else if c.rango < a.rango && c.rango < b.rango {
            [c, a, b]
        } else {
            [a, b, c]
        };
    }

for segment in line.lines() {
        let segment_length =
            (segment.end.x - segment.start.x).hypot(segment.end.y - segment.start.y);
        traversed += segment_length;
        if traversed > start_distance
            && traversed < end_distance
            && coordinates.last() != Some(&segment.end)
        {
            coordinates.push(segment.end);
        }
    }

for punto in anello.points() {
            calcolo.add_point(punto.y(), punto.x());
        }

for anello in polygon.interiors() {
        interne += area_anello(anello, Winding::Clockwise)?;
    }

for child in &collection.0 {
                collect_lines(child, operation, output)?;
            }

loop {
        if used[edge_index] {
            break;
        }
        let edge = &edges[edge_index];
        let forward = edge.start == current_node;
        if forward {
            for &coordinate in &edge.line.0 {
                if output.last() != Some(&coordinate) {
                    output.push(coordinate);
                }
            }
        } else {
            for &coordinate in edge.line.0.iter().rev() {
                if output.last() != Some(&coordinate) {
                    output.push(coordinate);
                }
            }
        }
        used[edge_index] = true;
        current_node = if forward { edge.end } else { edge.start };
        let incident = &adjacency[&current_node];
        if incident.len() != 2 {
            break;
        }
        let Some(next) = incident.iter().copied().find(|candidate| !used[*candidate]) else {
            break;
        };
        edge_index = next;
    }

for &coordinate in &edge.line.0 {
                if output.last() != Some(&coordinate) {
                    output.push(coordinate);
                }
            }

for &coordinate in edge.line.0.iter().rev() {
                if output.last() != Some(&coordinate) {
                    output.push(coordinate);
                }
            }

for line in lines {
        let start = EndpointKey::new(line.0[0]);
        let end = EndpointKey::new(
            *line
                .0
